import {setLogger, type Logger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry rejection diagnostics', () => {
  it('logs a nested location type rejection without its value (spec: specs/hal-engine-tool-input-validation/spec.md#11)', async () => {
    const records: unknown[] = [];
    const record: Logger['warn'] = (category, message, fields) => records.push({category, message, fields});
    setLogger({debug: record, info: record, warn: record, error: record});
    try {
      const registry = new ToolRegistry();
      const inputs: Record<string, unknown>[] = [];
      registry.register(
        {
          name: 'weather',
          description: 'Weather by location',
          inputSchema: {
            type: 'object',
            properties: {query: {type: 'object', properties: {location: {type: 'string'}}}},
          },
        },
        async input => {
          inputs.push(input);
          return JSON.stringify(input);
        }
      );

      const response = await registry.execute('weather', {query: {location: 8675309}});

      expect({response, inputs, records}).toEqual({
        response: {result: 'data/query/location: type must be string'},
        inputs: [],
        records: [
          {
            category: 'tool',
            message: 'input rejected',
            fields: {name: 'weather', result: 'data/query/location: type must be string'},
          },
        ],
      });
    } finally {
      setLogger();
    }
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.diagnostics.test.ts"
